<template><template v-if="['rounded','rect','square'].includes(value.shape)"><label class="checkbox-label"><input type="checkbox" :checked="value.individualCorners===true" :indeterminate="value.individualCorners===undefined" @change="emit('change','individualCorners',$event.target.checked)">Arrondis par coin</label><div v-if="value.individualCorners" class="position-grid"><label v-for="[key,label] in [['tl','Haut gauche'],['tr','Haut droit'],['bl','Bas gauche'],['br','Bas droit']]" :key="key">{{label}} · %<input type="number" min="0" max="50" step="1" :placeholder="multiple?'Mixte':''" :aria-label="'Arrondi '+label.toLowerCase()" :value="value.cornerRadii?.[key]??''" @input="$event.target.value!==''&&emit('corner',key,Math.max(0,Math.min(50,Number($event.target.value))))"></label></div><p class="field-help">Pourcentage du petit côté : les courbes restent régulières à l’étirement.</p></template></template>
